var FT={"Arathi Heritage":{"cat":"O","hb":"WoW","d":"Advantage against Charmed, and once in a while shrug off Unconscious.","full":"**Fey Ancestry.** You have Advantage on saving throws to avoid or end the Charmed condition.\n**Lethargy Resilience.** When you fail a saving throw to avoid or end the Unconscious condition, you can succeed instead. After you use this, you cannot use it again until you finish 1d4 Long Rests.","pre":"Human, World of Warcraft campaign"},"Child of the Sea (WoW)":{"cat":"O","hb":"WoW","d":"Hold your breath for 2 + Con modifier minutes and swim at your Speed.","full":"**Lasting Breath.** You can hold your breath for a number of minutes equal to 2 plus your Constitution modifier (minimum 1 minute).\n**Ocean Born.** You have a Swim Speed equal to your Speed.","pre":"Human, World of Warcraft campaign","fx":{"mv":{"swim":"speed"}}},"Clearcasting":{"cat":"G","hb":"WoW","d":"Free cantrip after a spell Critical Hit, and 1s on Force spell damage count as 2s.","full":"Raise Intelligence by 1, to a maximum of 20.\n**Clearcasting.** When you score a Critical Hit with a spell attack roll, you can use your Reaction to cast a cantrip that takes an action to cast.\n**Force Adept.** When you roll damage for a spell that deals Force damage, you can treat any 1 on a damage die as a 2.","pre":"Level 4+","asi":["INT"]},"Elusive Brawler":{"cat":"G","hb":"WoW","d":"Reaction: Dodge when you take damage.","full":"Raise Dexterity or Wisdom by 1, to a maximum of 20.\n**Reactive Dodge.** When you take damage, you can use your Reaction to take the Dodge action.","pre":"Level 4+, Dexterity 13+ or Wisdom 13+","asi":["DEX","WIS"]},"Enveloping Mist":{"cat":"G","hb":"WoW","d":"Healing wraps a creature in mist that cuts the next hit and then grants Temporary Hit Points.","full":"Raise Dexterity or Wisdom by 1, to a maximum of 20.\n**Enveloping Mist.** When you cast a spell or use a feature that restores Hit Points to a creature, wrap it in healing mist. Roll one of the dice of the healing and note the number as its Life Cocoon value. If an attack roll hits the creature before the start of its next turn, you can use your Reaction to reduce that attack's damage by the Life Cocoon value, and the mist ends. If the mist is still there at the start of the creature's next turn, the creature gains Temporary Hit Points equal to the value.","pre":"Level 4+, Dexterity 13+ or Wisdom 13+","asi":["DEX","WIS"]},"Fingers of Frost":{"cat":"G","hb":"WoW","d":"Your spells ignore Cold resistance and deal extra Cold damage to Restrained creatures.","full":"Raise Intelligence by 1, to a maximum of 20.\n**Cold Mastery.** Spells you cast ignore Resistance to Cold damage.\n**Frostbite.** When you deal Cold damage to a creature with the Restrained condition, it takes extra Cold damage. Roll a number of d4s equal to your Proficiency Bonus and add them.","pre":"Level 4+","asi":["INT"]},"Fists of Fury":{"cat":"G","hb":"WoW","d":"Clean hits on Unarmed and Light weapons, plus a damage bonus for each prior melee hit this turn.","full":"Raise Dexterity or Wisdom by 1, to a maximum of 20.\n**Clean Hits.** When you roll damage for an Unarmed Strike or a weapon with the Light property, you can treat any 1 on a damage die as a 2.\n**Combo Strikes.** When you deal damage to a creature with an Unarmed Strike, add +1 to the damage roll for each earlier melee attack roll that hit that creature in the same turn.","pre":"Level 4+, Dexterity 13+ or Wisdom 13+","asi":["DEX","WIS"]},"Hot Streak":{"cat":"G","hb":"WoW","d":"Your spells ignore Fire resistance and make burning worse.","full":"Raise Intelligence by 1, to a maximum of 20.\n**Fire Mastery.** Spells you cast ignore Resistance to Fire damage.\n**Ignite.** When a spell you cast deals Fire damage to a creature, it starts burning. When you deal Fire damage to a creature that is already burning, its burning damage increases by 1d4.","pre":"Level 4+","asi":["INT"]},"Inscription Adept":{"cat":"G","hb":"WoW","d":"Cast Illusory Script free once per Long Rest, then Glyph of Warding and Symbol at higher proficiency.","full":"Raise Intelligence, Wisdom, or Charisma by 1, to a maximum of 20.\n**Inscription Magic.** You learn Illusory Script and always have it prepared. You can cast it once without a spell slot and regain that free cast after a Long Rest. You can also cast it with spell slots, and you may use herbalism resources of the right value in place of its Material component. The ability you raised is your spellcasting ability for it.\n**Higher Spells.** As your proficiency in inscription grows you can cast more spells this way, each once per Long Rest. Journeyman (+3): Glyph of Warding. Artisan (+5): Symbol.","pre":"Level 4+, proficiency with Calligrapher's Supplies, Cartographer's Tools, or Painter's Supplies","asi":["INT","WIS","CHA"]},"Stagger and Sway":{"cat":"G","hb":"WoW","d":"Reduce damage by your Dex modifier, then pay it back as delayed Force damage.","full":"Raise Dexterity or Wisdom by 1, to a maximum of 20.\n**Defer Damage.** When you take damage, reduce it by your Dexterity modifier (minimum 1), then add a d6 to your Delayed Reaction pool. At the end of your turn, remove every die from the pool and roll them. You take Force damage equal to the total.\n**Purify.** As a Bonus Action, remove a number of dice equal to your Wisdom modifier from the pool.","pre":"Level 4+, Dexterity 13+ or Wisdom 13+","asi":["DEX","WIS"]},"Void Warrior":{"cat":"X","hb":"WoW","d":"Learn two Warlock cantrips that count as Ranger spells and use Wisdom.","full":"You learn two Warlock cantrips of your choice (Chill Touch and Mind Sliver are suggested). They count as Ranger spells for you, and Wisdom is your spellcasting ability for them. Whenever you gain a Ranger level you can replace one of them with another Warlock cantrip.","pre":"Demon Hunter Fighting Style","pick":[{"k":"c","t":"cantrip","n":2,"cls":"Warlock","title":"Two Warlock cantrips"}],"cls":"Demon Hunter"},"Will to Survive":{"cat":"O","hb":"WoW","d":"Ignore Incapacitated on your turn at the cost of one Exhaustion level.","full":"When you have the Incapacitated condition but not the Unconscious condition, you can ignore Incapacitated on your turn. If you do, you gain 1 Exhaustion level.","pre":"Human, World of Warcraft campaign"}};
