var SPC={"Dracthyr":{"size":"Medium","speed":30,"dark":60,"type":"Humanoid","traits":[["Darkvision","Darkvision 60 ft."],["Gliding Wings","In natural form and not Incapacitated, a fall reduces the distance counted for damage by up to 100 feet, and you glide 2 feet sideways per 1 foot you drop."],["Natural Weaponry","In natural form, Bonus Action: use wings or tail for an Unarmed Strike that can Shove a creature."],["Visage","Magic action: change between your natural form and a humanoid visage. You choose the visage look when you pick the species. Clothing, gear and game statistics do not change."],["Draconic Flight","From level 5, Bonus Action: gain a Fly Speed equal to your Speed for 10 minutes. After you use it, finish a Long Rest to use it again."]],"hb":"WoW"},"Draenei":{"size":"Medium","speed":30,"dark":60,"type":"Humanoid","spAb":"choose","spAbTrait":"Eredar Lineage","lin":{"label":"Eredar Lineage","opts":["Draenei","Krokul","Lightforged","Man'ari"]},"linRes":{"Draenei":"Necrotic","Krokul":"Poison","Lightforged":"Radiant","Man'ari":"Fire"},"linText":{"Draenei":"Resistance to Necrotic damage. You know Spare the Dying. Level 3: Healing Word. Level 5: Prayer of Healing.","Krokul":"Resistance to Poison damage. You know Poison Spray. Level 3: Ray of Sickness. Level 5: Hold Person.","Lightforged":"Resistance to Radiant damage. You know Sacred Flame. Level 3: Guiding Bolt. Level 5: Aid.","Man'ari":"Resistance to Fire damage. You know Fire Bolt. Level 3: Hellish Rebuke. Level 5: Darkness."},"traits":[["Darkvision","Darkvision 60 ft."],["Eredar Lineage","Pick Draenei, Krokul, Lightforged or Man'ari. You get the level 1 benefit now (a damage Resistance and a cantrip). At level 3 and level 5 you learn a higher-level spell. It is always prepared, you can cast it once per Long Rest without a slot, and you can also cast it with slots. Intelligence, Wisdom or Charisma is the spell ability, chosen with the species."],["Heroic Presence","When you cast a spell from your Eredar Lineage and have no Heroic Inspiration, you gain it. This works once, then returns after a Short or Long Rest."]],"hb":"WoW"},"Earthen":{"size":"Medium","speed":30,"dark":120,"type":"Humanoid","traits":[["Darkvision","Darkvision 120 ft."],["Azerite Surge","When you take the Attack action, you can swap one attack for a 15-foot Cone of Azerite. Creatures you choose in the Cone regain 1d10 Hit Points. Every other creature makes a Dexterity save (DC 8 + Constitution modifier + Proficiency Bonus) and takes 1d10 Radiant damage, or half on a success. The dice rise to 2d10 at level 5, 3d10 at level 11 and 4d10 at level 17. Uses equal your Proficiency Bonus per Long Rest."],["Earthen Resilience","Resistance to Poison damage and Advantage on saves to avoid or end the Poisoned condition."],["Ingest Minerals","You gain no Exhaustion levels from malnutrition."],["Quiet Contemplation","When you spend Hit Point Dice on a Short Rest, you regain 1 extra Hit Point per die spent."]],"hb":"WoW"},"Elf (WoW)":{"size":"Medium","speed":30,"dark":60,"type":"Humanoid","spAb":"choose","spAbTrait":"Azeroth Elven Lineage","lin":{"label":"Azeroth Elven Lineage","opts":["Blood Elf","Night Elf","Nightborne","Void Elf","High Elf"]},"linText":{"Blood Elf":"You know Prestidigitation, and can swap it for another Wizard cantrip after a Long Rest. Level 3: Detect Magic. Level 5: Arcane Vigor.","Night Elf":"Proficiency in Stealth. Level 3: Longstrider. Level 5: Pass without Trace.","Nightborne":"You know Arcane Pulse. Level 3: Faerie Fire. Level 5: Darkness.","Void Elf":"You know Mind Sliver. Level 3: Entropic Embrace. Level 5: Misty Step.","High Elf":"You know a Wizard cantrip, swappable after a Long Rest. Level 3: Detect Magic. Level 5: Misty Step."},"traits":[["Darkvision","Darkvision 60 ft."],["Elven Lineage","Pick Blood Elf, Night Elf, Nightborne, Void Elf or High Elf. You get the level 1 benefit now. At level 3 and level 5 you learn a higher-level spell. It is always prepared, you can cast it once per Long Rest without a slot, and you can also cast it with slots. Intelligence, Wisdom or Charisma is the spell ability, chosen with the species."],["Fey Ancestry","Advantage on saves to avoid or end the Charmed condition."],["Keen Senses","Proficiency in Insight, Perception or Survival."],["Trance","You do not sleep. You finish a Long Rest in 4 hours of light trance while staying aware."]],"skillPick":{"n":1,"from":["Insight","Perception","Survival"],"label":"Keen Senses"},"hb":"WoW"},"Forsaken":{"size":"Medium or Small","speed":30,"dark":60,"type":"Humanoid","traits":[["Darkvision","Darkvision 60 ft."],["Deathly Endurance","Resistance to Necrotic damage."],["Everlasting","You gain no Exhaustion levels from dehydration, malnutrition or suffocation. You do not need sleep and magic cannot put you to sleep. You finish a Long Rest in 4 hours of inactive, motionless rest while staying conscious."],["Touch of the Grave","When you damage a creature, roll a number of d4s equal to your Proficiency Bonus. It takes that total as extra Necrotic damage and you regain Hit Points equal to it. After you use it, finish a Long Rest to use it again."],["Will of the Forsaken","Advantage on saves to avoid or end the Charmed or Frightened condition."]],"hb":"WoW"},"Goblin (WoW)":{"size":"Small","speed":30,"dark":60,"type":"Humanoid","traits":[["Darkvision","Darkvision 60 ft."],["Fey Ancestry","Advantage on saves to avoid or end the Charmed condition."],["Fury of the Small","When you hit a larger creature with an attack or spell, add extra damage equal to your Proficiency Bonus, of the same type as the other damage. Once per turn. Uses equal your Proficiency Bonus per Long Rest."],["Nimble Escape","Bonus Action each turn: Disengage or Hide."]],"hb":"WoW"},"Haranir":{"size":"Medium","speed":30,"dark":120,"type":"Humanoid","spAb":"choose","spAbTrait":"Haranir Magic","skillPick":{"n":2,"from":["Nature","Survival"],"label":"Gift of the World Tree"},"traits":[["Darkvision","Darkvision 120 ft."],["Gift of the World Tree","Proficiency in Nature and Survival."],["Haranir Magic","You know Druidcraft and Thorn Whip. Level 3: Entangle. Level 5: Spike Growth. Each is always prepared and castable once per Long Rest without a slot. Intelligence, Wisdom or Charisma is the spell ability, chosen with the species."]],"hb":"WoW"},"Mechagnome":{"size":"Small","speed":30,"dark":0,"type":"Construct","traits":[["Built for Success","Add 1d4 to one D20 Test after you roll it, before the result is known. Uses equal your Proficiency Bonus per Long Rest."],["Emergency Fail-Safe","When you become Bloodied, use your Reaction to spend one Hit Point Die, roll it and regain that roll plus your Constitution modifier (minimum 1) Hit Points. After you use it, finish a Short or Long Rest to use it again."],["Mechanical Nature","Resistance to Poison damage. Advantage on saves to avoid or end the Paralyzed or Poisoned condition. You gain no Exhaustion levels from dehydration, malnutrition or suffocation."],["Sentry's Rest","You do not sleep. You finish a Long Rest in 6 hours of inactive, motionless rest while staying conscious."],["Specialized Design","Proficiency with two tools of your choice."]],"hb":"WoW"},"Pandaren":{"size":"Medium","speed":30,"dark":60,"type":"Humanoid","traits":[["Darkvision","Darkvision 60 ft."],["Bouncy","Resistance to Bludgeoning damage from falling."],["Inner Peace","When you spend Hit Point Dice on a Short Rest, you regain 1 extra Hit Point per die spent."],["Quaking Palm","When you hit a creature with a melee attack on your turn, your movement does not provoke Opportunity Attacks from it until the end of your turn."]],"hb":"WoW"},"Tauren":{"size":"Medium","speed":30,"dark":0,"type":"Humanoid","lin":{"label":"Tauren Lineage","opts":["Mulgore Tauren","Highmountain Tauren","Taunka"]},"linRes":{"Taunka":"Cold"},"linText":{"Mulgore Tauren":"When you take the Attack action, swap one attack for a war stomp. Each creature of your choice within a 5-foot Emanation makes a Constitution save or has the Stunned condition until the end of your turn. You cannot use it while Prone, flying, climbing or swimming. The save DC is 8 + Proficiency Bonus + Strength, Constitution or Wisdom modifier, chosen with the lineage.","Highmountain Tauren":"Action: move up to your Speed without provoking Opportunity Attacks and through other creatures' spaces. Each Medium or smaller creature whose space you enter makes a Strength save or takes damage equal to your Proficiency Bonus plus Strength modifier and has the Prone condition. A creature takes this damage once per turn.","Taunka":"+1 bonus to Armor Class and Resistance to Cold damage."},"traits":[["Horns","Your Unarmed Strike can deal Piercing damage equal to 1d6 plus Strength modifier instead of its normal damage."],["Goring Rush","After you Dash and move at least 20 feet, make one Unarmed Strike as a Bonus Action."],["Hammering Horns","After you hit a creature with a melee attack as part of the Attack action, Bonus Action: Shove it with an Unarmed Strike if it is within 5 feet. You can push it up to 10 feet."],["Tauren Lineage","Pick Mulgore Tauren, Highmountain Tauren or Taunka. Any save DC from it equals 8 + Proficiency Bonus + your Strength, Constitution or Wisdom modifier, chosen with the lineage."]],"hb":"WoW"},"Troll (WoW)":{"size":"Medium","speed":30,"dark":60,"type":"Humanoid","lin":{"label":"Troll Lineage","opts":["Amani Troll","Darkspear Troll","Zandalari Troll"]},"linText":{"Amani Troll":"When you spend Heroic Inspiration, you regain 1 expended Hit Point Die.","Darkspear Troll":"When you Dash, Difficult Terrain of ice, rubble, snow or undergrowth costs you no extra movement until the end of your turn.","Zandalari Troll":"If you roll a 1 on the d20 of a D20 Test, you gain Heroic Inspiration at the end of the turn."},"traits":[["Darkvision","Darkvision 60 ft."],["Bloodied Frenzy","While Bloodied, you have Advantage on attack rolls."],["Troll Healing","When you spend Hit Point Dice on a Short Rest, each die heals its maximum roll plus your Constitution modifier."],["Troll Lineage","Pick Amani Troll, Darkspear Troll or Zandalari Troll."]],"hb":"WoW"},"Vulpera":{"size":"Small","speed":30,"dark":60,"type":"Humanoid","traits":[["Darkvision","Darkvision 60 ft."],["Fire Resistance","Resistance to Fire damage."],["Nose for Trouble","The first time you take damage after you roll Initiative, reduce that damage by your level (minimum 0)."],["Vulpera Nimbleness","You can move through the space of any creature one size larger than you, but you cannot stop there."]],"hb":"WoW"},"Worgen":{"size":"Medium","speed":30,"dark":60,"type":"Humanoid","traits":[["Darkvision","Darkvision 60 ft."],["Darkflight","Bonus Action: take a bestial form for 1 minute or until you end it as a Bonus Action. You gain Temporary Hit Points equal to twice your Proficiency Bonus. In the form your Speed rises by 10 feet, you have Resistance to Necrotic damage, and as a Reaction you can move up to 10 feet without Opportunity Attacks when a creature ends its turn within 5 feet of you. Uses equal your Proficiency Bonus per Long Rest."],["Instinctual Shift","When you roll Initiative with a Darkflight use left, you can use it at once with no action."]],"hb":"WoW"}};
