var GR=[["Cenarion War Hippogryph",2000,0,"Mount","Use the Hippogriff stat block. Carrying capacity 510 lb. Needs Renown 50+ with the Cenarion Circle. If your Renown there drops below 50 it stops obeying you."],["Dire Wolf",750,0,"Mount","Use the Dire Wolf stat block. Carrying capacity 510 lb. Needs Renown 10+ with Orgrimmar."],["Elekk",400,0,"Mount","Use the Giant Goat stat block. Carrying capacity 510 lb. Needs Renown 10+ with the Exodar."],["Giant Goat",400,0,"Mount","Use the Giant Goat stat block. Carrying capacity 510 lb. Needs Renown 10+ with Ironforge."],["Giant Hyena",750,0,"Mount","Use the Giant Hyena stat block. Carrying capacity 480 lb. Needs Renown 10+ with the Steamwheedle Cartel."],["Giant Seahorse",1000,0,"Mount","Use the Giant Seahorse stat block. Carrying capacity 450 lb."],["Gryphon",2000,0,"Mount","Use the Griffon stat block. Carrying capacity 540 lb. Needs Renown 25+ with the Alliance."],["Hawkstrider",150,0,"Mount","Use the Axe Beak stat block. Carrying capacity 420 lb. Needs Renown 10+ with Silvermoon City."],["Kodo",100,0,"Mount","Use the Giant Lizard stat block. Carrying capacity 450 lb. Needs Renown 10+ with Thunder Bluff."],["Mechanostrider",450,0,"Mount","Use the Mechanostrider stat block. Carrying capacity 420 lb. Needs Renown 10+ with Gnomeregan."],["Nightsaber",750,0,"Mount","Use the Tiger stat block. Carrying capacity 510 lb. Needs Renown 10+ with Darnassus."],["Pandarian Dragon Turtle",500,0,"Mount","Use the Pandarian Dragon Turtle stat block. Carrying capacity 480 lb. Needs Renown 10+ with the Huojin or the Tushui."],["Raptor",1000,0,"Mount","Use the Allosaurus stat block. Carrying capacity 570 lb. Needs Renown 10+ with the Darkspear Tribe."],["Talbuk",150,0,"Mount","Use the Elk stat block. Carrying capacity 480 lb."],["Warhorse",400,0,"Mount","Use the Warhorse stat block. Carrying capacity 540 lb. Needs Renown 10+ with Stormwind."],["Warhorse Skeleton",500,0,"Mount","Use the Warhorse Skeleton stat block. Carrying capacity 540 lb. Needs Renown 10+ with Undercity."],["Wind Rider",2000,0,"Mount","Use the Giant Bat stat block. Carrying capacity 450 lb. Needs Renown 25+ with the Horde."],["Zhevra",200,0,"Mount","Use the Elk stat block. Carrying capacity 480 lb."],["Flying Machine",0,0,"Vehicle","A small gyrocopter. Crew 1, AC 19, 27 Hit Points, speed 4 mph, cargo 0.15 tons. It cannot be bought. A character with expert engineering builds it with 2,000 gp of resources. Powered vehicle: it travels at its speed in miles per hour and needs Fuel (10 lb, 1 gp per 8 hours of travel)."],["Goblin Trike",400,0,"Vehicle","A three-wheeled motor vehicle. Crew 1, AC 19, 27 Hit Points, speed 3 mph, cargo 0.3 tons. Needs Renown 10+ with any goblin cartel. Powered vehicle: it travels at its speed in miles per hour and needs Fuel (10 lb, 1 gp per 8 hours of travel)."],["Mechano-Hog",4000,0,"Vehicle","A Horde motorcycle with an optional sidecar. Crew 1, 1 passenger, AC 19, 27 Hit Points, speed 4 mph, cargo 0.4 tons. Needs Renown 10+ with the Horde. Powered vehicle: it travels at its speed in miles per hour and needs Fuel (10 lb, 1 gp per 8 hours of travel)."],["Mekgineer's Chopper",4000,0,"Vehicle","An Alliance motorcycle with an optional sidecar. Crew 1, 1 passenger, AC 19, 27 Hit Points, speed 4 mph, cargo 0.4 tons. Needs Renown 10+ with the Alliance. Powered vehicle: it travels at its speed in miles per hour and needs Fuel (10 lb, 1 gp per 8 hours of travel)."],["Fuel",1,10,"Adventuring Gear","Powers a vehicle for 8 hours of travel. A character with the alchemy profession can craft it."]];
